name: Publish Daily Repository Status

on:
  schedule:
    # Runs at 00:00 UTC every day
    - cron: '0 0 * * *'

permissions:
  contents: read
  issues: write

jobs:
  publish:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Publish daily status
        uses: actions/github-script@v6
        with:
          script: |
            const now = new Date();
            const twoDaysAgo = new Date(now.getTime() - 48 * 60 * 60 * 1000);
            const dateStr = now.toISOString().split('T')[0];

            // Fetch merged PRs in the last 48 hours
            const mergedResponse = await github.rest.pulls.list({
              ...context.repo,
              state: 'closed',
              sort: 'updated',
              direction: 'desc',
              per_page: 100,
            });
            const recentMerged = mergedResponse.data.filter(pr =>
              pr.merged_at && new Date(pr.merged_at) >= twoDaysAgo
            );

            // Fetch open PRs
            const openResponse = await github.rest.pulls.list({
              ...context.repo,
              state: 'open',
              per_page: 100,
            });
            const openPRs = openResponse.data;

            // Build markdown body
            let body = `## 🌟 Daily Repository Status — ${dateStr}\n\n`;
            body += `Great momentum today! The team shipped ${recentMerged.length} PRs in the last two days and is pushing forward on agents, Azure Functions, Aspire, and infrastructure quality. Here's your snapshot. 🚀\n\n`;

            body += `## ✅ Recently Merged (Last 48 Hours)\n\n`;
            body += `| # | Title | Author |\n|---|-------|--------|\n`;
            recentMerged.forEach(pr => {
              const title = pr.title.replace(/\|/g, '\\|');
              const author = pr.user.login;
              body += `| [#${pr.number}](${pr.html_url}) | ${title} | @${author} |\n`;
            });

            body += `\n## 🔄 Open Pull Requests (Needs Attention)\n\n`;
            body += `| # | Title | Author |\n|---|-------|--------|\n`;
            openPRs.forEach(pr => {
              const title = pr.title.replace(/\|/g, '\\|');
              const author = pr.user.login;
              body += `| [#${pr.number}](${pr.html_url}) | ${title} | @${author} |\n`;
            });

            // Create or update the daily status issue
            const issueTitle = `Daily Repository Status — ${dateStr}`;
            const existingIssues = await github.rest.issues.listForRepo({
              ...context.repo,
              state: 'open',
              per_page: 100,
            });

            const existing = existingIssues.data.find(issue => issue.title === issueTitle);
            if (existing) {
              await github.rest.issues.update({
                ...context.repo,
                issue_number: existing.number,
                body,
              });
            } else {
              await github.rest.issues.create({
                ...context.repo,
                title: issueTitle,
                body,
              });
            }
